(()=>{'use strict';const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];const input=$('[data-base-input]'),err=$('[data-error]'),buttons=$$('[data-base-choice]'),outs={bin:$('[data-out-bin]'),oct:$('[data-out-oct]'),dec:$('[data-out-dec]'),hex:$('[data-out-hex]')};if(!input)return;let mode='10';const abs=v=>v<0n?-v:v;const parse=(raw,base)=>{let s=raw.trim().replace(/[,_\s]/g,'');if(!s)throw Error('値を入力してください');if(s.length>512)throw Error('入力が長すぎます');let neg=false;if(s[0]==='-'||s[0]==='+'){neg=s[0]==='-';s=s.slice(1)}if(!s)throw Error('数値として読めません');let v;if(base==='2'){s=s.replace(/^0b/i,'');if(!/^[01]+$/.test(s))throw Error('2進数は0と1だけで入力してください');v=BigInt('0b'+s)}else if(base==='8'){s=s.replace(/^0o/i,'');if(!/^[0-7]+$/.test(s))throw Error('8進数は0〜7で入力してください');v=BigInt('0o'+s)}else if(base==='16'){s=s.replace(/^0x/i,'');if(!/^[0-9a-f]+$/i.test(s))throw Error('16進数は0〜9とA〜Fで入力してください');v=BigInt('0x'+s)}else{if(!/^\d+$/.test(s))throw Error('10進数は0〜9で入力してください');v=BigInt(s)}return neg?-v:v};const groupBits=v=>{const neg=v<0n,s=abs(v).toString(2),pad=(4-s.length%4)%4,x='0'.repeat(pad)+s,parts=x.match(/.{1,4}/g)||[x];return(neg?'-':'')+parts.join(' ')};const fmt=(v,b,upper=false)=>(v<0n?'-':'')+abs(v).toString(b)[upper?'toUpperCase':'toString']();const setMode=m=>{mode=m;buttons.forEach(b=>{const on=b.dataset.baseChoice===m;b.classList.toggle('primary',on);b.setAttribute('aria-pressed',on?'true':'false')});input.inputMode=m==='10'?'numeric':'text';run()};const run=()=>{try{const v=parse(input.value,mode);err.classList.remove('show');outs.bin.textContent=groupBits(v);outs.oct.textContent=(v<0n?'-':'')+abs(v).toString(8);outs.dec.textContent=v.toString(10);outs.hex.textContent=(v<0n?'-':'')+abs(v).toString(16).toUpperCase();$$('[data-copy-kind]').forEach(b=>b.dataset.copy=outs[b.dataset.copyKind].textContent);if(window.CBL&&CBL.track&&!run.tracked){run.tracked=true;CBL.track('tool_use',{tool_name:'base-converter'})}}catch(e){err.textContent=e.message;err.classList.add('show');Object.values(outs).forEach(x=>x.textContent='—')}};const copy=async(v,b)=>{try{await navigator.clipboard.writeText(v);const t=b.textContent;b.textContent='コピー済み';setTimeout(()=>b.textContent=t,1200)}catch{prompt('コピーしてください',v)}};input.addEventListener('input',run);buttons.forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.baseChoice)));$$('[data-base-example]').forEach(b=>b.addEventListener('click',()=>{input.value=b.dataset.baseExample;setMode(b.dataset.baseMode)}));$$('[data-copy-kind]').forEach(b=>b.addEventListener('click',()=>copy(b.dataset.copy||'',b)));setMode('10')})();